  "claim": {
    "component_id": "C011.component",
    "value": "Removal tests must hold the equipment, agreed start deadline and other test conditions fixed.",
    "scope": "Comparison of tested reductions within the selected case.",
    "provenance": {
      "refs": [
        {"source_id": "P009", "role": "SUPPORT"},
        {"source_id": "P008", "role": "CONTEXT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P009 explicitly requires these controls; P008 identifies the selected case."
    }
  },
  "signal_basis": {
    "component_id": "C011.signal_basis",
    "value": "Group or complement removal tests keep other conditions fixed and apply the same repetition rule; a smaller configuration repeatedly reproduces lateness while specified further removals cease to do so. Inconsistent or uncertain outcomes remain unresolved.",
    "scope": "Controlled comparisons among configurations of the selected case.",
    "provenance": {
      "refs": [
        {"source_id": "P009", "role": "SUPPORT"},
        {"source_id": "P015", "role": "SUPPORT"},
        {"source_id": "P018", "role": "SUPPORT"},
        {"source_id": "P008", "role": "CONTEXT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the comparison operation, common repetition rule, unresolved-outcome handling and observed pattern."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C011.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported as a procedural control requirement; no unresolved empirical relation is needed."
    }
  },
  "rationale": "Holding nonremoved conditions fixed makes the configurations comparable: otherwise changes in equipment, deadline or background conditions could account for differences in lateness. This licenses the stated control requirement within the selected case.",
  "uncertainty": "Other test conditions are not enumerated, but that does not undermine the bounded requirement to hold them fixed.",
  "anomalies": []
}
